        if _, err := client.Act(ctx, stagehand.ActInstruction("open the filters panel"), nil); err != nil {
        	return err
        }
        if _, err := client.Act(ctx, stagehand.ActInstruction("choose 4-star rating"), nil); err != nil {
        	return err
        }
